using System;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text.Json;
using Mantle.Core.Look;
using Xunit;

namespace Mantle.Core.Tests.Look;

/// <summary>
/// lane r14-ci-look: the accent profiles (look-sync CONTRACT "Accent profiles", 2026-11-25; accent.js at c29ba47).
/// accent-v2.json next to this file is look-sync's test/fixtures/accent-v2.json at c29ba47, byte for byte (git blob
/// ff637b25; generated by look-sync's test/fixtures/accent-v2.gen.js, never hand-edited): the 124 shared vectors every port
/// must pass. The other facts are look-sync's test/accent-v2.test.js, ported.
/// </summary>
public class AccentV2Tests
{
    static string Fixture([CallerFilePath] string here = "") => Path.Combine(Path.GetDirectoryName(here)!, "accent-v2.json");

    static string Rgba(AccentTokens t, double a) => "rgba(" + t.R + ", " + t.G + ", " + t.B + ", " + a.ToString("0.##", CultureInfo.InvariantCulture) + ")";

    [Fact]
    public void Every_shared_accent_vector_passes_all_124()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Fixture()));
        var vectors = doc.RootElement.GetProperty("vectors").EnumerateArray().ToArray();
        Assert.Equal(124, vectors.Length);
        int passed = 0;
        foreach (var v in vectors) {
            string profile = v.GetProperty("profile").GetString()!, theme = v.GetProperty("theme").GetString()!;
            int hue = v.GetProperty("hue").GetInt32();
            var want = v.GetProperty("tokens");
            var t = Accent.Tokens(hue, theme, profile)!;
            string at = profile + " " + theme + " " + hue;
            Assert.True(want.GetProperty("acc").GetString() == t.Acc, at + " acc: want " + want.GetProperty("acc").GetString() + ", got " + t.Acc);
            Assert.True(want.GetProperty("strong").GetString() == t.Strong, at + " strong: want " + want.GetProperty("strong").GetString() + ", got " + t.Strong);
            Assert.True(want.GetProperty("on").GetString() == t.On, at + " on: want " + want.GetProperty("on").GetString() + ", got " + t.On);
            var al = Accent.Alpha(theme != "light");
            Assert.Equal(Rgba(t, al.Soft), t.Soft);
            Assert.Equal(Rgba(t, al.Line), t.Line);
            passed++;
        }
        Assert.Equal(124, passed);
        // the base hues the file was generated against are the port's
        var b = doc.RootElement.GetProperty("base");
        foreach (var p in new[] { "steel", "islands" })
            foreach (var th in new[] { "dark", "light" })
                Assert.Equal(b.GetProperty(p).GetProperty(th).GetInt32(), Accent.BaseHue(p, th));
    }

    [Fact]
    public void Islands_at_its_base_hue_185_is_ice_blue_exactly()
    {
        Assert.Equal(185, Accent.IslandsHue);
        Assert.Equal(185, Accent.BaseHue("islands"));
        Assert.Equal(212, Accent.BaseHue("islands", "light"));
        var t = Accent.Tokens(185, "dark", "islands")!;
        Assert.Equal("#a9e7ed", t.Acc);
        Assert.Equal("#c4f0f4", t.Strong);
        Assert.Equal("#052a2f", t.On);
        Assert.Equal("rgba(169, 231, 237, 0.14)", t.Soft);
        Assert.Equal("rgba(169, 231, 237, 0.42)", t.Line);
        // one degree away moves at most 1 step per channel (acc, strong) and 2 (on): no jump when the slider first moves
        static int Step(string a, string b) => new[] { 1, 3, 5 }.Max(i => Math.Abs(Convert.ToInt32(a.Substring(i, 2), 16) - Convert.ToInt32(b.Substring(i, 2), 16)));
        foreach (int h in new[] { 184, 186 }) {
            var n = Accent.Tokens(h, "dark", "islands")!;
            Assert.True(Step(n.Acc, t.Acc) <= 1 && Step(n.Strong, t.Strong) <= 1 && Step(n.On, t.On) <= 2, "hue " + h);
        }
    }

    /// What the light islands profile gives at 185 today (reported to the EM: it is NOT #083f49; the light look is not
    /// authored in look-sync yet, so islands light = steel light at hue 185).
    [Fact]
    public void Islands_light_is_steel_light_until_an_app_builds_its_light_look()
    {
        for (int h = 0; h <= 360; h++) Assert.Equal(Accent.Tokens(h, "light", "steel"), Accent.Tokens(h, "light", "islands"));
        var t = Accent.Tokens(185, "light", "islands")!;
        Assert.Equal("#4d7f84", t.Acc);
        Assert.Equal("#3c696d", t.Strong);
        Assert.Equal("#ffffff", t.On);
        Assert.Equal("rgba(77, 127, 132, 0.4)", t.Line);
    }

    [Fact]
    public void Steel_is_the_default_and_unchanged_for_no_profile_and_an_unknown_one()
    {
        Assert.Equal(212, Accent.BaseHue(null));
        Assert.Equal(212, Accent.BaseHue("nonsense"));
        Assert.Equal("islands", Accent.ProfileOf("islands"));
        Assert.Equal("steel", Accent.ProfileOf(null));
        for (int h = 0; h <= 360; h++)
            foreach (var theme in new[] { "dark", "light" }) {
                var s = Accent.Tokens(h, theme, "steel");
                Assert.Equal(s, Accent.Tokens(h, theme));
                Assert.Equal(s, Accent.Tokens(h, theme, "x"));
            }
        Assert.Equal("#9fb4cc", Accent.Tokens(212, "dark")!.Acc);
        Assert.Null(Accent.Tokens(null, "dark", "islands"));
        Assert.Throws<ArgumentOutOfRangeException>(() => Accent.Tokens(400, "dark", "islands"));
    }
}
